from __future__ import annotations

import re
from dataclasses import dataclass, field
from datetime import date, timedelta
from decimal import Decimal, ROUND_CEILING, ROUND_HALF_UP

# --- constants -------------------------------------------------------------

MINUTES_PER_STEP = 6
STEP_HOURS = Decimal("0.1")
DAILY_REGULAR_CAP_HOURS = Decimal("8")
WEEKLY_REGULAR_CAP_HOURS = Decimal("40")

DAILY_OT_MULTIPLIER = Decimal("1.25")
WEEKLY_OT_MULTIPLIER = Decimal("1.5")

CENT = Decimal("0.01")

# Inline rate card: matter code -> hourly rate (Decimal, USD/hour).
RATE_CARD: dict[str, Decimal] = {
    "ACME": Decimal("450.00"),
    "GLOBEX": Decimal("300.00"),
}


class BillingError(ValueError):
    """Raised for invalid timesheet input."""


# --- data model -------------------------------------------------------------


@dataclass(frozen=True)
class TimeEntry:
    """A raw timesheet entry. `minutes` is the RAW (unrounded) duration."""

    matter: str
    day: date
    minutes: int

    def __post_init__(self) -> None:
        if self.minutes <= 0:
            raise BillingError(
                f"zero-length and negative entries are rejected "
                f"(got {self.minutes} min on {self.day} for {self.matter})"
            )
        if self.matter not in RATE_CARD:
            raise BillingError(
                f"unknown matter {self.matter!r}; rate card has "
                f"{sorted(RATE_CARD)}"
            )

    @property
    def rounded_minutes(self) -> int:
        """Raw minutes rounded UP to a 6-minute increment."""
        steps = -(-self.minutes // MINUTES_PER_STEP)  # ceil div
        return steps * MINUTES_PER_STEP

    @property
    def rounded_hours(self) -> Decimal:
        return Decimal(self.rounded_minutes) / Decimal(60)


_DUR_RE = re.compile(r"^\s*(?:(\d+)\s*h)?\s*(?:(\d{1,2})\s*m)?\s*$", re.I)


def parse_duration(text: str) -> int:
    """Parse '3h07m', '45m', '2h' into raw minutes."""
    m = _DUR_RE.match(text)
    if not m or (m.group(1) is None and m.group(2) is None):
        raise BillingError(f"unparseable duration: {text!r}")
    hours = int(m.group(1) or 0)
    minutes = int(m.group(2) or 0)
    total = hours * 60 + minutes
    if total <= 0:
        raise BillingError(f"zero-length entry rejected: {text!r}")
    return total


def entry(matter: str, day: date, duration: str | int) -> TimeEntry:
    minutes = parse_duration(duration) if isinstance(duration, str) else duration
    return TimeEntry(matter=matter, day=day, minutes=minutes)


# --- billing ----------------------------------------------------------------


@dataclass
class MatterTotals:
    regular_hours: Decimal = field(default_factory=lambda: Decimal("0"))
    daily_ot_hours: Decimal = field(default_factory=lambda: Decimal("0"))
    weekly_ot_hours: Decimal = field(default_factory=lambda: Decimal("0"))

    @property
    def amount(self) -> Decimal:
        rate = RATE_CARD[_matter_of_key(self)]
        return (
            self.regular_hours * rate
            + self.daily_ot_hours * rate * DAILY_OT_MULTIPLIER
            + self.weekly_ot_hours * rate * WEEKLY_OT_MULTIPLIER
        ).quantize(CENT, rounding=ROUND_HALF_UP)


# small helper so MatterTotals knows its matter without duplicating storage
_MATTER_ATTR = "__matter__"


def _matter_of_key(totals: "MatterTotals") -> str:
    return getattr(totals, _MATTER_ATTR)


@dataclass
class Invoice:
    week_start: date
    by_matter: dict[str, MatterTotals] = field(default_factory=dict)

    def totals_for(self, matter: str) -> MatterTotals:
        if matter not in self.by_matter:
            self.by_matter[matter] = MatterTotals()
            setattr(self.by_matter[matter], _MATTER_ATTR, matter)
        return self.by_matter[matter]

    @property
    def total(self) -> Decimal:
        return sum((t.amount for t in self.by_matter.values()), Decimal("0.00"))


def compute_invoice(entries: list[TimeEntry]) -> Invoice:
    """Bill a list of entries assumed to belong to one ISO week."""
    if not entries:
        raise BillingError("no entries to bill")

    days = sorted({e.day for e in entries})
    week_start = days[0] - timedelta(days=days[0].weekday())
    for d in days:
        if not (week_start <= d < week_start + timedelta(days=7)):
            raise BillingError(f"entry on {d} falls outside week {week_start}")

    invoice = Invoice(week_start=week_start)

    # Pass 1 (per day, chronological): split each entry's rounded hours into
    # regular-candidate (<8h into the day) and daily-OT (>8h into the day).
    # Each split carries a reference to its owning entry so pass 2 can pull
    # weekly OT back out of the regular pool without touching daily-OT hours.
    regular_splits: list[tuple[TimeEntry, Decimal]] = []
    for day in days:
        elapsed = Decimal("0")
        for e in sorted((x for x in entries if x.day == day), key=lambda x: x.id_order):
