            if reg > 0:
                regular_splits.append((e, reg))
            if dot > 0:
                invoice.totals_for(e.matter).daily_ot_hours += dot
            elapsed += h

    # Pass 2 (weekly): weekly OT takes only non-daily-OT hours. If the
    # regular-candidate pool exceeds 40h, remove the excess from the LATEST
    # regular splits and reclassify those hours at 1.5x.
    total_regular = sum((h for _, h in regular_splits), Decimal("0"))
    weekly_excess = max(
        Decimal("0"), total_regular - WEEKLY_REGULAR_CAP_HOURS
    )
    remaining = weekly_excess
    for e, h in reversed(regular_splits):
        if remaining <= 0:
            break
        take = min(h, remaining)
        invoice.totals_for(e.matter).weekly_ot_hours += take
        remaining -= take
        h -= take
